<template><main class="login"><section><div class="brand">智排 <small>GBSCHED</small></div><h1>医院智能排班系统</h1><p>以规则驱动排班，以数据守护每一班。</p></section><el-card class="login-card"><h2>欢迎登录</h2><el-form :model="form" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.username" placeholder="admin / supervisor / doctor"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="loading" class="wide">进入工作台</el-button></el-form><el-alert title="演示密码均为 admin123" type="info" :closable="false"/></el-card></main></template><script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import api from '../api/http';import {saveAuth} from '../stores/auth';const router=useRouter(),loading=ref(false),form=reactive({username:'admin',password:'admin123'});async function submit(){loading.value=true;try{saveAuth(await api.post('/auth/login',form));router.push('/')}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}</script>